void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float mask = 0, fog=0, trail = 0;
vec2 uv1 = (uv_orig-0.5)*uAspect.xy + pos;
vec2 p, q = multiply(uv1, mat2(_qa))/zoom, t=0, uvt;
vec3 S = 0, C = vec3( 1.0 , 2.0 , 3.0 ), col, scr, scm;
for (int i = 0; i < trails; i++)
{
float j=i/trails;
p = q* (1.0 - zz*j);
p+= 0.03* sin (pow(i+1.,vec2( 17.0 , 23.0 ) / 371.0)*T)*vec2( 1.0 , 3.0 );
mask = max(mask,sat(10-300*max(abs(p.x),.75*abs(p.y))));
col =  (cos(C * 14.0*cos(i)) + 1.0)*(1.0 + roam_cos);
uvt = p + vec2(j, 0.0 );
scr = texture(sampler_pw_noise_lq, fract(.2*uvt));
uvt += vec2(T*.1,T*(1.0 + j));
scm = texture(sampler_main, 1.5*uvt.yx/uAspect.xy);
trail = 1.0 / length (p / (vec2( 1.0 ,scm.r * 16.0)));
trail += q21*mask*scr.r / length (p / (vec2( 2.0 ,128.0 * scr.g)));
S += trail *   0.005 * col;
S += vb/length(p)* (sat(1.0 - pow((BPMtime)%trails-i, 2.0 )) +
sat(1.0 - pow((BPMtime * 2.0)%trails-i, 2.0 )) * 2.0*col);
fog += scm.g* abs(p.x);
S+= scm.g*0.7;
  fragColor = vec4(ret, 1.0);
}

